use super::{ThemeName, VimPalette, s};

impl ThemeName {
    pub(in crate::theme) fn vim_palette(self) -> Option<&'static VimPalette> {
        match self {
            Self::VimBlue => Some(&BLUE),
            Self::VimCatppuccin => Some(&CATPPUCCIN),
            Self::VimDarkblue => Some(&DARKBLUE),
            Self::VimDefault => Some(&DEFAULT),
            Self::VimDelek => Some(&DELEK),
            Self::VimDesert => Some(&DESERT),
            Self::VimElflord => Some(&ELFLORD),
            Self::VimEvening => Some(&EVENING),
            Self::VimHabamax => Some(&HABAMAX),
            Self::VimIndustry => Some(&INDUSTRY),
            Self::VimKoehler => Some(&KOEHLER),
            Self::VimLunaperche => Some(&LUNAPERCHE),
            Self::VimMorning => Some(&MORNING),
            Self::VimMurphy => Some(&MURPHY),
            Self::VimNovum => Some(&NOVUM),
            Self::VimPablo => Some(&PABLO),
            Self::VimPeachpuff => Some(&PEACHPUFF),
            Self::VimQuiet => Some(&QUIET),
            Self::VimRetrobox => Some(&RETROBOX),
            Self::VimRon => Some(&RON),
            Self::VimShine => Some(&SHINE),
            Self::VimSlate => Some(&SLATE),
            Self::VimSorbet => Some(&SORBET),
            Self::VimTorte => Some(&TORTE),
            Self::VimUnokai => Some(&UNOKAI),
            Self::VimWildcharm => Some(&WILDCHARM),
            Self::VimZaibatsu => Some(&ZAIBATSU),
            Self::VimZellner => Some(&ZELLNER),
            _ => None,
        }
    }
}

